#include <cmath>
#include <numbers>
#include <type_traits>

static bool near(double a, double b) { return std::abs(a - b) < 1e-9; }

TEST("Shape is abstract and has a virtual destructor") {
  CHECK(std::is_abstract_v<Shape>);
  CHECK(std::has_virtual_destructor_v<Shape>);
}

TEST("calls through a Shape pointer reach the real class") {
  std::unique_ptr<Shape> c = std::make_unique<Circle>(1.0);
  std::unique_ptr<Shape> r = std::make_unique<Rectangle>(2.0, 3.0);
  CHECK(near(c->area(), std::numbers::pi));
  CHECK_EQ(c->name(), std::string("circle"));
  CHECK(near(r->area(), 6.0));
  CHECK_EQ(r->name(), std::string("rectangle"));
}

static int g_destroyed = 0;
struct TrackedCircle : Circle {
  using Circle::Circle;
  ~TrackedCircle() { ++g_destroyed; }
};

TEST("deleting through Shape* runs the derived destructor") {
  g_destroyed = 0;
  { std::unique_ptr<Shape> s = std::make_unique<TrackedCircle>(1.0); }
  CHECK_EQ(g_destroyed, 1);
}

TEST("total_area and largest") {
  std::vector<std::unique_ptr<Shape>> v;
  v.push_back(std::make_unique<Rectangle>(1.0, 2.0));
  v.push_back(std::make_unique<Circle>(1.0));
  v.push_back(std::make_unique<Rectangle>(1.0, 1.0));
  CHECK(near(total_area(v), 3.0 + std::numbers::pi));
  CHECK(largest(v) == v[1].get());
  CHECK(largest({}) == nullptr);
}

TEST("make_shape parses valid specs") {
  auto c = make_shape("circle 2");
  auto r = make_shape("rect 3 4");
  CHECK(c != nullptr && r != nullptr);
  CHECK(near(c->area(), 4 * std::numbers::pi));
  CHECK(near(r->area(), 12.0));
}

TEST("make_shape rejects bad specs") {
  for (const char* bad : {"", "circle", "circle -1", "circle 2 3", "rect 3", "square 2", "rect 3 x"}) {
    if (make_shape(bad) != nullptr) throw cl::Failure{std::string("accepted \"") + bad + "\""};
  }
}

