#include <memory>
#include <numbers>
#include <sstream>
#include <string>
#include <vector>

class Shape {
 public:
  virtual ~Shape() = default;  // so deleting through a Shape* destroys the whole object
  virtual double area() const = 0;
  virtual std::string name() const = 0;
};

class Circle : public Shape {
 public:
  explicit Circle(double r) : r_(r) {}
  double area() const override { return std::numbers::pi * r_ * r_; }
  std::string name() const override { return "circle"; }

 private:
  double r_;
};

class Rectangle : public Shape {
 public:
  Rectangle(double w, double h) : w_(w), h_(h) {}
  double area() const override { return w_ * h_; }
  std::string name() const override { return "rectangle"; }

 private:
  double w_, h_;
};

double total_area(const std::vector<std::unique_ptr<Shape>>& shapes) {
  double sum = 0;
  for (const auto& s : shapes) sum += s->area();
  return sum;
}

const Shape* largest(const std::vector<std::unique_ptr<Shape>>& shapes) {
  const Shape* best = nullptr;
  for (const auto& s : shapes)
    if (!best || s->area() > best->area()) best = s.get();
  return best;
}

std::unique_ptr<Shape> make_shape(const std::string& spec) {
  std::istringstream in(spec);
  std::string kind;
  in >> kind;
  // `(in >> std::ws).eof()` checks nothing but whitespace is left over.
  if (kind == "circle") {
    double r;
    if (in >> r && r > 0 && (in >> std::ws).eof()) return std::make_unique<Circle>(r);
  } else if (kind == "rect") {
    double w, h;
    if (in >> w >> h && w > 0 && h > 0 && (in >> std::ws).eof()) return std::make_unique<Rectangle>(w, h);
  }
  return nullptr;
}
